using System;
using System.Collections.Generic;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
namespace HdrPilot {
public static partial class Guide {
 sealed class Topic {public string Name,Intro;public string[] Sections;public Topic(string name,string intro,params string[] sections){Name=name;Intro=intro;Sections=sections;}}
 static readonly Topic[] Topics={
 new Topic("Disinstallazione e originali Steam","Il primo avvio usa inglese. La lingua scelta nella schermata iniziale viene conservata ai successivi avvii. Disinstalla / ripristina rimuove anche la precedente installazione OptiScaler di Autopilot quando sono disponibili il registro supportato e i backup validi. Non è necessario ripristinare Autopilot e poi disinstallarlo una seconda volta. ReShade HDR, UE4SS e gli altri componenti separati vengono conservati.","Backup e residui","I backup Autopilot utilizzati vengono spostati nella copia di recupero dell’app. Backup diversi per lo stesso file fermano l’operazione. La rimozione comprende i file elencati nel registro supportato; file sconosciuti e cartelle vuote possono restare. Recupera operazione permette di annullare la rimozione.","Originali Steam","Verifica integrità Steam controlla e recupera i file distribuiti da Steam. Un backup esterno non certifica da solo gli originali. La verifica non sostituisce la rimozione dei file aggiunti dalle mod. L’app non dichiara la cartella originale senza questa verifica.","Percorsi lunghi","L’app usa il supporto ai percorsi lunghi di .NET Framework 4.8 e dichiara questa capacità a Windows. Non modifica il registro di sistema. Strumenti esterni e specifiche configurazioni Windows possono avere limiti propri."),
 new Topic("Componenti e pulsanti","I pulsanti ReShade e RenoDX diventano gialli quando il componente è rilevato nei file del gioco, anche se installato da un’altra app. Restano gialli riaprendo il gioco nella libreria e permettono di aggiornarlo. Dopo la rimozione tornano blu. Le scelte DLSS 5 di stile, posizione, passaggi, loader e FG diventano gialle quando corrispondono ai parametri esplicitamente letti dalla configurazione installata. Anche nero e formato HDR distinguono valori letti e nuove scelte. Conserva e valori predefiniti assenti non vengono presentati come applicati. Giallo indica configurato su disco, non un effetto misurato in gioco. Il canale stabile/nightly è giallo solo quando verificabile; non viene dedotto dalla semplice presenza di ReShade. Installato non significa attivo in gioco.","HDR e Neural Rendering","Un add-on DLSS 5 già presente non blocca da solo l’installazione ReShade o RenoDX HDR. Rimane il controllo contro un secondo iniettore NR durante l’installazione OptiScaler; i controlli sui loader e sui backup restano attivi."),
 new Topic("Aggiornamenti e dati","Una nuova build non richiede di reinstallare i componenti nei giochi.","Stato installato","ReShade e RenoDX sono rilevati dai file accanto all’eseguibile scelto, anche se installati da un’altra app. Il pannello mostra subito la versione e propone Aggiorna ReShade se è presente. Giallo indica una build OptiScaler rilevata o un canale ReShade verificato dal registro e dall’hash della DLL. Blu indica una scelta o un’azione da applicare: cliccare non significa installare. Per ReShade precedente o esterno, se il canale stabile/nightly non è verificabile nessuno dei due è giallo, anche se la versione installata è mostrata. Stabile e nightly indicano la versione desiderata per il prossimo download, non certificano il canale della DLL attuale. Installato non significa attivo: verifica il menu in gioco.","Preferenze e backup","Sostituire soltanto l’eseguibile mantiene data. Se estrai una nuova cartella HDR-Unlock accanto alle precedenti, la nuova build riutilizza la cartella dati valida più recente, inclusi backup, preferenze e tasti overlay. Il collegamento è in data-location.txt: conserva anche la vecchia cartella che contiene i dati. Backup e dati apre la cartella effettivamente usata. Non vengono unite copie divergenti e i dati propri di una build hanno precedenza.","Cartelle spostate","Se la nuova build è in un’altra posizione, conserva o copia la cartella data insieme all’eseguibile. I componenti restano rilevabili nei giochi, ma senza i backup non è possibile garantire il ripristino originale."),
 new Topic("Attività e avanzamento","In basso trovi la fase corrente e una barra sempre visibile.","Durante l’installazione","Download e controlli senza una misura disponibile usano una barra animata. Durante l’applicazione la barra conta i file completati: non è una stima del tempo residuo. Attendi Operazione completata prima di avviare il gioco.","Registro semplice","Attività recenti mostra i passaggi principali, senza elencare ogni DLL e percorso. Puoi chiuderlo o ridimensionarlo trascinando la barra. Dettagli tecnici apre il registro completo, utile per diagnosticare errori."),
 new Topic("Xbox / Game Pass","Scansiona cerca anche i giochi PC installati tramite Xbox e Gaming Services. Non mostra il catalogo cloud e non verifica il tuo abbonamento: include anche giochi acquistati nello stesso store.","Libreria e copertine","Le etichette sulle miniature indicano soltanto Steam oppure Xbox / Game Pass. Le miniature Xbox sono nella stessa libreria di Steam e usano le immagini locali del pacchetto con la migliore risoluzione utile. Le immagini riempiono lo stesso spazio di Steam senza deformazioni; quelle larghe vengono centrate e ritagliate in modo simmetrico ai lati. La scritta dello store compare solo nella fascia inferiore. Libreria… permette di aggiungere una cartella XboxGames o GamePass. I collegamenti WindowsApps vengono risolti verso la cartella effettiva, evitando duplicati.","Avvio e impostazioni","Avvia gioco usa il pacchetto Windows registrato. Se Windows impedisce la lettura dell’EXE, il controllo x64 usa il manifest Xbox e verifica che il target sia elencato in MicrosoftGame.config. Questo permette di preparare il modello NR senza rimuovere le protezioni Windows; non garantisce il caricamento della mod. Il target.exe indica dove installare le mod; la scelta API non forza parametri di avvio nei giochi Xbox. HDR INI è disponibile solo per Unreal verificato e configurazioni trovate, comprese WinGDK. ReShade e OptiScaler richiedono compatibilità con l’edizione Xbox del gioco, non basta il supporto dell’edizione Steam.","Cartelle protette","I pacchetti rimasti dentro WindowsApps sono mostrati ma non modificati. L’app non cambia permessi o proprietà di Windows. Se disponibile, usa Gestisci nell’app Xbox per spostare o reinstallare in una cartella modificabile, poi scansiona. Per riparare i file usa le funzioni dell’app Xbox. Conserva sempre la cartella data di HDLSS."),
 new Topic("Primi passi","HDR, DLSS 5 e mod grafiche. Senza complicazioni., quando la loro versione di Unreal lo consente. Il picco scritto negli INI è una richiesta al motore, non un tetto garantito a tutti gli effetti successivi. Applica HDR nel metodo UE5 modifica solo Engine.ini e GameUserSettings.ini con backup: non installa ReShade, RenoDX o UE4SS. ReShade/RenoDX rimane un metodo separato. La scelta non rimuove componenti e alcune mod richiedono HDR del motore: segui i requisiti della mod per evitare due conversioni HDR. L’overlay misura i pixel Windows con entrambi i metodi e senza mod. I parametri del motore sono distinti e richiedono telemetria UE4SS recente; non sostituiscono le misure dei pixel.","1. Scegli il gioco","Scansiona le librerie Steam e Xbox / PC Game Pass installate. Seleziona una copertina e controlla il motore rilevato. La presenza di UE5 non garantisce che tutte le opzioni HDR siano supportate.","2. Imposta e applica","Attiva HDR in Windows, scegli il monitor e chiudi il gioco. Consigliati compila i campi; Applica HDR salva nei file e crea un backup. La barra in basso rimane sempre accessibile.","3. Avvia","Premi Avvia gioco nella barra fissa. Se ci sono modifiche non salvate, l’app lo segnala prima di avviare Steam."),
 new Topic("Libreria e file","Associa ogni profilo ai file del gioco corretto.","Scansione e copertine","La scansione usa i giochi Steam installati. Libreria… aggiunge un’altra cartella SteamLibrary. Le copertine arrivano dalla cache Steam; puoi scegliere un’immagine locale.","Cartella impostazioni","Nella sezione HDR del motore trovi il gruppo Cartella e configurazione. Se manca la cartella, avvia il gioco una volta e seleziona quella contenente GameUserSettings.ini, normalmente in AppData/Local/Progetto/Saved/Config/Windows.","Sezione del file","Alcuni giochi usano una sezione UserSettings personalizzata. L’app la preferisce quando è univoca; se ci sono più possibilità, scegli quella usata dal gioco. Il nome interno del progetto può differire dal titolo."),
 new Topic("Monitor e consigli","Il modello rilevato aiuta a scegliere un punto di partenza; non sostituisce una calibrazione.","Scegli il display","Se usi più monitor, seleziona quello del gioco. Rileva di nuovo aggiorna l’elenco. L’app non cambia la modalità nel menu del monitor e non attiva HDR in Windows.","Alienware AW3423DW","Sono disponibili Peak 1000 nominale, Peak 1000 personalizzato a 1060 nit e True Black 400 nominale. Scegli la stessa modalità sul monitor. Il profilo 1060 è personalizzato; il dato EDID non è una misura del tuo pannello.","Altri monitor","Quando disponibile, viene proposto il picco HDR dichiarato nell’EDID. Se il dato manca, inserisci il valore calibrato. Mezzitoni 15 nit, UI 100% e nero Base Unreal sono riferimenti del motore."),
 new Topic("Regolazioni HDR","I pulsanti ? accanto ai valori aprono spiegazioni dettagliate senza allungare il pannello.","Picco e mezzitoni","Il picco richiesto al gioco non aumenta la capacità fisica del monitor. I mezzitoni regolano il grigio al 18%: non sono il bianco. Parti da 15 nit e confronta la stessa scena prima e dopo ogni modifica.","Interfaccia","100% significa moltiplicatore 1, non 100 nit. Se l’interfaccia abbaglia, riduci la percentuale; alcuni HUD personalizzati possono ignorare il parametro.","Punto di nero","Il nero fisico OLED può essere zero. Il parametro Unreal è logaritmico: Base corrisponde a −4, Quasi zero a −6. Scrivere 0 in quel parametro significherebbe 1 nit. Quasi zero non elimina necessariamente neri sollevati dal gioco."),
 new Topic("HDR avanzato","Nel gruppo HDR avanzato attiva l’interruttore solo quando vuoi applicare anche questi valori.","Conservazione dei valori","Con l’interruttore spento, le opzioni avanzate già presenti rimangono invariate. I campi mostrano valori letti o iniziali. La disponibilità dipende dalla versione di Unreal e dal gioco.","Formato e luminanza UI","Il formato associa scRGB a Rec.709 oppure HDR10 PQ a Rec.2020. La luminanza base dell’interfaccia è moltiplicata per la percentuale UI: ad esempio, 300 nit × 50% = 150 nit.","Scena e interruttori","Il moltiplicatore ACES usa percentuali intere. Compressione colori ACES e Composizione UI HDR sono interruttori: il primo agisce sui colori brillanti, il secondo sulla fusione dell’HUD. I pulsanti ? spiegano ciascuna opzione."),
 new Topic("Overlay della scena","Il picco della scena viene dai pixel catturati; il limite configurato resta un riferimento separato.","Come aprirlo","Premi Apri overlay live, poi porta il gioco in primo piano, in finestra senza bordi, interamente sul monitor selezionato. Usa la scorciatoia per mostrare e nascondere. Nascondendo si sospende la cattura.","Cosa misura","L’analizzatore cerca pixel HDR FP16/scRGB tramite Windows e calcola picco, media e minimo dell’area del gioco. Include HUD e barre nere, ma esclude il riquadro del nostro overlay e un margine di otto pixel: eventuali picchi presenti solo sotto quel riquadro non vengono misurati. Punta a circa cinque letture al secondo: può perdere un lampo tra due acquisizioni.","Limiti della lettura","Misura il segnale digitale, non i nit fisici del pannello. Non salva immagini. Se Windows nega l’accesso, il formato non è adatto o il gioco non è in primo piano, mostra il motivo. La lettura è stata confermata dall’utente in Hellraiser; gli altri giochi restano da verificare."),
 new Topic("Parametri del motore","Questa vista è diversa dall’analizzatore della scena.","UE4SS facoltativo","Nel gruppo Strumenti e parametri motore trovi lo stato rilevato: UE4SS presente, modulo HDRPilotTelemetry installato, abilitazione configurata e dati recenti sono verifiche distinte. Aggiorna stato lettore ripete il controllo. Un file vecchio non prova che il lettore stia funzionando. Installa UE4SS + lettore scarica il pacchetto ufficiale stabile e mostra il piano prima di installarlo accanto al vero eseguibile Unreal x64. Se UE4SS è presente, Attiva lettore UE4SS aggiunge solo la telemetria. Sono riconosciute le installazioni nella cartella del gioco e nella sottocartella ue4ss. Override personalizzati, runtime duplicati e dwmapi.dll occupato richiedono un controllo manuale. La compatibilità dipende dal gioco: verifica un nuovo UE4SS.log. Disattiva lettore ferma solo la telemetria; Recupera operazione annulla la nuova installazione con il registro salvato. I giochi Unreal aggiunti manualmente vengono cercati anche in Engine/Plugins per leggere e aggiornare le DLL DLSS SR/RR/FG. Le funzionalità devono essere già supportate dal gioco.","Come leggere le colonne","SALVATO proviene dagli INI; IN GIOCO proviene dalle variabili del motore. Un picco impostato a 1060 non dimostra che i pixel della scena raggiungano 1060 nit. Dati vecchi o assenti non vengono mostrati come attuali."),
 new Topic("Tasti e diagnostica","Configura una combinazione libera e usa il log quando l’overlay non legge.","Scorciatoia","Il riquadro HDR → Cambia tasto permette lettere con Ctrl/Shift/Alt oppure tasti funzione ammessi. Home, End/Fine, PgUp/Pagina su, PgDn/Pagina giù, Ins e Del/Canc si possono usare anche senza modificatori. F10 senza modificatori resta riservato alla console; F12 è escluso. Le combinazioni occupate vengono segnalate e la scelta viene conservata nella cartella data.","Tasto OptiScaler","In DLSS 5 trovi Tasto del menu OptiScaler: premi Premi un tasto… e poi il tasto desiderato sulla tastiera. Usa un tasto singolo; Esc annulla. Conserva lascia il valore del gioco invariato. Applica impostazioni scrive la scelta con backup. Il tasto ReShade è separato ed è configurabile nella pagina HDR.","Overlay non visibile","Usa finestra senza bordi e chiudi eventuali vecchie copie di HDLSS: possono tenere occupato il tasto. La nuova finestra viene nascosta realmente, senza lasciare un riquadro opaco.","Lettura non disponibile","Apri l’overlay, entra nel gioco per qualche secondo, poi premi Diagnostica overlay. Il log distingue attesa del gioco, errore di identificazione e rifiuto della cattura. Non registra immagini o tasti premuti."),
 new Topic("Backup e portable","Copertina carica un’immagine JPG, PNG o BMP per il gioco selezionato, anche aggiunto manualmente. Una copia viene salvata nei dati dell’app. Preferisci un’immagine verticale ad alta risoluzione. Aggiungi gioco permette di selezionare un eseguibile di qualsiasi client e conservarlo nella libreria. Avvia gioco apre quell’eseguibile; può essere necessario il client del gioco. Indietro riporta alla home. Guida, Diagnostica e Backup sono nella barra laterale. La libreria mostra i titoli Steam installati. Le copertine crescono con la finestra e mantengono la stessa dimensione in HDR e DLSS 5. La libreria usa uno sfondo uniforme senza immagini del gioco. HDR via INI è disabilitato quando UE5 non è riconosciuto; ReShade/RenoDX richiede una mod per quel titolo. Eseguibile e grafica… permette di scegliere dove installare i componenti. Negli altri motori l’API va scelta anche nel gioco. Tieni la cartella data insieme all’eseguibile. In alto a destra nella home scegli lingua e aspetto chiaro, scuro o come Windows. I due riquadri HDR e DLSS 5 mantengono tutte le opzioni precedenti nelle rispettive sezioni. Le preferenze si salvano automaticamente. Il Registro operazioni in basso mostra i passaggi: aprilo e trascina la barra dorata sopra il testo per ingrandirlo o ridurlo con il mouse; Apri log apre il file testuale conservato in data/logs.","Salvataggio protetto","Applica crea una copia dei due INI. Se Engine.ini è di sola lettura, l’attributo viene rimosso temporaneamente e ripristinato dopo l’operazione. Le altre impostazioni del gioco vengono conservate.","Ripristina","Ripristina recupera i file interi del backup scelto, comprese le impostazioni presenti a quella data. Lo stato precedente al ripristino viene salvato a sua volta.","Aggiornamento e versione","Chiudi la copia precedente e sostituisci l’eseguibile conservando data. La versione è 1.0. HDLSS è il nuovo nome di HDR Unlock; conserva la cartella data e i backup durante l’aggiornamento. Il programma non è firmato digitalmente: sono possibili avvisi Windows di reputazione."),
 new Topic("DLSS 5 e GPU","Seleziona un gioco nella libreria e apri DLSS 5 sotto le copertine. L’iniezione viene eseguita tramite OptiScaler, con la build della community selezionata.","RTX 4000 e 5000","L’app prova a leggere GPU e driver tramite NVIDIA. Per RTX 4000 serve il runtime NR di compatibilità indicato dagli autori; RTX 5000 usa quello originale. Il minimo driver documentato dalla build NR è 616.56, ma il risultato va verificato per gioco e release. Il driver non viene installato o sostituito dall’app.","Aiuti per ogni scelta","Sotto i gruppi trovi la spiegazione della scelta selezionata. Passa il mouse su un altro pulsante per leggerne l’effetto prima di sceglierlo. Il punto ? spiega l’intero gruppo. Le opzioni disabilitate mantengono gli aiuti disponibili.","Prima o dopo l’upscaling","Con la build wilsjo2, Prima applica il modello prima dell’ingrandimento: se l’ingresso ha meno pixel, può ridurre il lavoro del modello. Dopo elabora il risultato ingrandito e può costare più tempo GPU. Confronta resa e prestazioni nella stessa scena. Conserva lascia la posizione esistente o il default della build.","Passaggi e MFG sono diversi","Un passaggio esegue il modello una volta; due o tre ripetono l’elaborazione e possono aumentare trasformazione, costo e artefatti. Non creano fotogrammi intermedi: quello è il compito della Frame Generation, descritta nell’argomento dedicato.","Build e regolazioni","Dagherbou, wilsjo2 e y4my4my4m sono varianti della community, non versioni ufficiali NVIDIA. Inizia con un passaggio; 75% riduce il costo del modello, 100% usa la piena risoluzione d’ingresso. Stile e intensità modificano il risultato artistico. I pulsanti ? spiegano ciascuna scelta.","Installazione","Installa OptiScaler scarica il pacchetto standard dal repository dell’autore e verifica il digest pubblicato quando disponibile. Puoi anche scegliere una cartella già estratta. Il runtime nvngx_dlssnr.dll viene conservato se presente o selezionato separatamente. Prima della scrittura appare l’elenco dei file. Non usare nei giochi protetti da anti-cheat."),
 new Topic("Frame Generation / MFG","Genera fotogrammi intermedi per aumentare la fluidità. Il moltiplicatore richiesto non misura gli FPS e non aumenta nella stessa proporzione la reattività dei comandi.","1. Scegli chi genera i fotogrammi","In DLSS 5 trovi Fluidità / Frame Generation. Conserva è la scelta iniziale: non cambia i parametri FG. OptiScaler usa l’upscaler del gioco e un insieme di componenti NVIDIA FG già installato. FG del gioco richiede di attivare DLSS Frame Generation nel menu del gioco; HDLSS ne richiede il moltiplicatore tramite OptiScaler. Non attivare due sistemi FG concorrenti.","2. Scegli il moltiplicatore","Parti da 2×: un fotogramma reale più uno generato. 3× genera due intermedi, 4× tre e così via fino a 6×. I pulsanti non adatti alla GPU vengono disabilitati. I valori superiori dipendono dal supporto del runtime e del gioco; selezionarli non dimostra che siano attivi.","RTX 4000","Il percorso NVIDIA standard è limitato a 2×. Per provare valori superiori scegli y4my4my4m, FG del gioco e MFG RTX 4000 · sperimentale. Lo sblocco Ada è non ufficiale NVIDIA: può avere una cadenza irregolare e smettere di funzionare dopo un aggiornamento driver. L’app controlla che l’installazione dichiari AdaMfgUnlock; in caso contrario aggiorna prima la build. Le altre build non ricevono questo parametro.","RTX 5000","Puoi richiedere i moltiplicatori superiori senza lo sblocco Ada. Il massimo effettivo dipende dai componenti caricati e dal supporto del gioco. I controlli espongono moltiplicatori fissi, non MFG dinamico.","3. Applica e verifica","Chiudi il gioco e premi Applica impostazioni, oppure Installa OptiScaler per una nuova installazione. Controlla l’anteprima e conferma il backup. Riavvia il gioco. Il controllo verifica GPU, file FG/Streamline x64 e, per il moltiplicatore nativo, Streamline almeno 2.7.1. Le dipendenze mancanti non vengono scaricate da questa funzione. Usa il menu e i log del componente per verificare il supporto e il valore applicato; il contatore FPS da solo non basta.","Se non funziona","Il percorso configurato è pensato per DirectX 12; DX11 e Vulkan richiedono verifiche separate. Disattiva OptiScaler rimuove la sua generazione e i suoi override, ma non spegne FG nativa nel gioco. Conserva mantiene lo stato attuale: non annulla una modifica già applicata. Le copie precedenti sono nei backup. L’integrazione è stata testata su configurazioni isolate e nell’interfaccia, non collaudata in gioco in questa sessione."),
 new Topic("DLL e versioni","Il riepilogo Componenti installati mostra subito le versioni SR, RR, FG e del modello NR lette dai file, oppure Non installato. Passando il mouse sul riepilogo trovi i percorsi; Controlla file e percorsi ripete il controllo e mostra i percorsi. Per file multipli confronta gli hash SHA-256 e distingue file identici, file diversi da controllare e confronto non disponibile. Più percorsi non provano un conflitto o più effetti attivi; hash identici non certificano compatibilità o caricamento. Nessuna DLL viene cancellata automaticamente. I backup sono esclusi. Si aggiorna dopo installazioni e ripristini. Non certifica il caricamento in gioco. Le DLL di SR, RR e FG sono componenti diversi dal runtime Neural Rendering. Per lo scambio viene verificata l’architettura x64 della DLL presente, anche quando Windows protegge la lettura dell’eseguibile Xbox. La DLL deve essere accessibile e quella nuova deve superare i controlli NVIDIA; le cartelle protette e gli altri blocchi restano esclusi.","Aggiornamento NVIDIA","I quattro pulsanti Super Resolution, Ray Reconstruction, Frame Generation e Neural Rendering sono raggruppati sotto Componenti installati, senza puntini nei nomi. Neural Rendering apre la scelta del modello DLSS 5. Gli altri tre aprono direttamente il componente scelto, rilevato anche nelle sottocartelle Unreal. All’apertura caricano le ultime 10 versioni dal catalogo, con la più recente selezionata. Se il componente manca, lo segnalano senza sostituire un’altra DLL. Carica ultime 10 usa il catalogo pubblico DLSS Swapper, che include DLL provenienti da SDK, driver e giochi. Installa versione scelta scarica dal suo archivio e verifica hash, firma NVIDIA e versione interna. Ultima da NVIDIA usa invece il repository ufficiale NVIDIA. I cataloghi possono aggiornarsi in momenti diversi. La firma NVIDIA e l’identità del componente devono risultare valide prima dello scambio.","TechPowerUp e importazione","TechPowerUp apre la pagina del componente. Scarica ed estrai la versione desiderata, poi usa Importa DLL. Vedi la versione presente e quella scelta prima di confermare. Se i file sono identici, nessuna modifica viene effettuata.","Ripristino","Ripristina DLL precedenti recupera lo stato prima del primo scambio di HDLSS. Una DLL più recente non aggiunge Ray Reconstruction o Frame Generation se il gioco non le implementa e non abilita MFG su una GPU non supportata."),
 new Topic("ReShade e RenoDX","Nella sezione HDR scegli il gestore Unreal Engine 5 oppure ReShade + RenoDX. La scelta del pannello viene ricordata per gioco; non modifica da sola i file. Add-on e shader offre AutoHDR di Lilium (uscita HDR sperimentale), Pumbo (conversione con uscita HDR già attiva), Lilium (analisi e tone mapping), qUINT e SweetFX (effetti, non HDR automatico). Seleziona un pulsante e premi Installa selezionato: scarica dall’autore e mostra i file con backup. Gli shader vanno attivati e regolati in ReShade. Rimuovi selezionato agisce sul singolo pacchetto. AutoHDR non va usato con anti-cheat o insieme a RenoDX/HDR del motore. Nessuna compatibilità universale; non è una classifica di download.","Stabile o nightly","La pagina HDR mostra direttamente i pulsanti per scegliere la stabile ufficiale da reshade.me e la nightly del ramo main di crosire/reshade tramite nightly.link. Entrambe usano il supporto completo agli add-on. I pacchetti vengono scaricati durante l’installazione e letti come archivi senza eseguire il setup.","Mod e regolazioni HDR","Installa / aggiorna RenoDX riconosce anche i giochi elencati nella sezione Unreal Engine Extended, usando il download condiviso e le note specifiche: Mortal Shell II richiede il percorso HDR Engine.ini secondo il catalogo. Per le righe UE Extended che indicano esattamente Engine.ini, l’installer prepara anche l’uscita HDR10/Rec.2020 del motore e l’aggiornamento LUT, abilita RenoDX con Upgrade Path Off e tone mapper HDR. Conserva la calibrazione RenoDX; gli INI hanno un backup separato recuperabile da Backup e dati. Rimuovere il solo add-on non ripristina automaticamente questi INI. AutoHDR concorrente ferma l’installazione. Altri profili richiedono le istruzioni specifiche dell’autore. Cerca automaticamente il nome del gioco nel catalogo ufficiale e scarica il collegamento x64 pubblicato dall’autore, senza chiedere un file. Mostra origine, stato della mod e anteprima prima di applicare con backup. Se la mod è distribuita soltanto su Nexus Mods, Installa / aggiorna RenoDX apre il download assistito: conferma il download gratuito sul sito e lascia aperta la finestra. L’app rileva uno ZIP RenoDX con titolo del gioco e ID della mod nel nome, con spazi o trattini, nella cartella Download di Windows o nella cartella scelta e ricordata, attende il completamento, estrae e verifica l’add-on x64 e apre l’anteprima con backup. Mantieni il nome originale; se il browser salva altrove, usa Cartella download… prima di scaricare. Annulla ferma l’attesa. Controlla anche le cartelle Download e Downloads alla radice dei dischi locali: se una sola contiene il pacchetto del gioco, la sceglie automaticamente. Un unico archivio già scaricato viene rilevato senza riaprire il browser, ma non viene certificato come ultima versione. Più pacchetti corrispondenti, più add-on o componenti extra non vengono installati automaticamente. Sono supportati ZIP con un solo add-on HDR e documentazione. Il nome non certifica l’origine: controlla mod e gioco nell’anteprima. RAR/7z richiedono ancora l’importazione locale dopo estrazione. Non servono password Nexus nell’app. Se il titolo manca, ci sono più mod o manca un download diretto supportato, spiega il motivo: non sceglie mod simili e non confonde demo ed edizioni complete. Il catalogo può distribuire snapshot sperimentali: consulta le note dell’autore. Importa mod RenoDX locale resta separato per i file scelti manualmente e non certifica che siano aggiornati. Le regolazioni avvengono dal menu ReShade in gioco, normalmente Home. Segui le note della mod: alcune richiedono uscita HDR del motore, altre una conversione SDR. La selezione del gestore non disinstalla una mod precedente.","Compatibilità e ripristino","ReShade usa il loader già riconosciuto o viene collegato tramite OptiScaler. DLL sconosciute, doppioni e file cambiati dopo l’anteprima fermano la scrittura. Disinstalla ReShade è accanto a Installa ReShade nella pagina HDR: rimuove la copia aggiunta da HDLSS oppure recupera la versione precedente, se esisteva già. Mostra i file prima della conferma. RenoDX resta su disco ma richiede ReShade per funzionare. Ripristina RenoDX gestisce separatamente il backup della mod. Prima di rimuovere OptiScaler, usa Disinstalla ReShade se dipende da quel loader."),
 new Topic("Mod e ripristino","Pulisci Neural Rendering e Pulisci ReShade rimuovono i file riconosciuti anche senza registro di installazione, mostrando prima l’elenco e conservando una copia in data/dlss-recovery. La pulizia non ripristina una mod precedente. ReShade include configurazione standard, shader nella cartella reshade-shaders e add-on HDR RenoDX riconosciuti; i preset personalizzati e gli add-on sconosciuti sono conservati. Neural Rendering include OptiScaler, modello NR e add-on NR riconosciuti; le DLL del gioco e MFG separato sono conservati. Se ReShade dipende da OptiScaler, pulisci prima ReShade. Non viene garantita la rimozione di ogni residuo di mod sconosciute; le cartelle vuote possono restare. Con wilsjo2, Prima dell’upscaling applica il modello prima di SR: imposta RunBeforeSR e disattiva FinishedPicture, DeferredDLSS e ResidualAcrossRR, mantenendo ApplyModel attivo. Conserva lascia questi percorsi invariati. Due passaggi ripetono il modello due volte e costano più GPU: non sono due fotogrammi generati. Prima di installare, la schermata controlla i loader e i registri delle installazioni esistenti. Disinstalla / ripristina nella sezione DLSS 5 riguarda OptiScaler: se non è rilevato né registrato, il pulsante è disabilitato. ReShade e una mod MFG autonoma non vengono rimossi con quel pulsante. Se Neural Rendering è abilitato e manca il modello, Installa OptiScaler e Applica impostazioni scaricano automaticamente la variante NR dal repository community RankFTW/rhi-repo: compatibilità per RTX 4000, originale per RTX 5000. Un modello x64 già presente viene conservato. Download e hash vengono verificati prima dell’anteprima; modello e configurazione sono applicati insieme con backup. La compatibilità effettiva va verificata in gioco.","Installazione Autopilot","Il registro dlss5-autopilot.json permette di riconoscere la build e l’elenco dei file. Disinstalla mette da parte i file elencati e ripristina i backup originali presenti. Se gli originali non sono disponibili, usa Verifica integrità Steam: una semplice rimozione non certifica gli originali del gioco.","ReShade, RenoDX e UE4SS","Un loader sconosciuto non viene sovrascritto. OptiScaler conserva il loader già riconosciuto; ReShade64.dll, se presente, può essere caricato dalla sua opzione dedicata. I componenti estranei al piano rimangono invariati. Altri add-on di Neural Rendering vengono segnalati per evitare una doppia elaborazione. Il pannello DLSS 5 Swapper Overlay riconosciuto tramite SHA-256 viene conservato e non blocca Installa OptiScaler. Questa eccezione riguarda soltanto il file verificato: versioni sconosciute o modificate restano da verificare, anche se il nome contiene overlay. Un add-on RenoDX Neural Rendering separato continua a bloccare una seconda installazione NR.","Backup e recupero","I backup e le copie di recupero sono nella cartella data: conservala insieme all’app. Recupera operazione consente di annullare una rimozione tramite il suo transaction.json. Il ripristino si ferma se i file sono stati modificati nel frattempo. Installazioni senza registro riconosciuto richiedono il disinstallatore della loro app.")

 };
 public static Window Create(Window owner){var topics=Core.Pref.Language=="it"?Topics:EnglishTopics;StackPanel body;Window window=Dialogs.Create(owner,"Guida di HDLSS",out body);window.Width=960;window.MaxWidth=SystemParameters.WorkArea.Width-40;window.MaxHeight=SystemParameters.WorkArea.Height-40;var layout=new Grid{Height=Math.Max(380,Math.Min(570,SystemParameters.WorkArea.Height-170)),Margin=new Thickness(0,12,0,0)};layout.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(215)});layout.ColumnDefinitions.Add(new ColumnDefinition());var menu=new StackPanel{Margin=new Thickness(0,0,18,0)};var menuScroll=new ScrollViewer{Content=menu,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};layout.Children.Add(menuScroll);var content=new StackPanel{Margin=new Thickness(22,0,18,12)};var scroll=new ScrollViewer{Content=content,VerticalScrollBarVisibility=ScrollBarVisibility.Auto};Grid.SetColumn(scroll,1);layout.Children.Add(scroll);body.Children.Add(layout);var buttons=new List<Button>();Action<int> select=index=>{content.Children.Clear();for(int i=0;i<buttons.Count;i++){buttons[i].Background=new SolidColorBrush((Color)ColorConverter.ConvertFromString(i==index?"#41331E":"#1B222C"));buttons[i].Foreground=new SolidColorBrush((Color)ColorConverter.ConvertFromString(i==index?"#E6AC50":"#BBC4D0"));}var topic=topics[index];var heading=Dialogs.Text(topic.Name,24);heading.Foreground=new SolidColorBrush(Color.FromRgb(230,172,80));content.Children.Add(heading);content.Children.Add(Dialogs.Text(topic.Intro,13));for(int n=0;n<topic.Sections.Length;n+=2){var h=Dialogs.Text(topic.Sections[n],15);h.Foreground=new SolidColorBrush(Color.FromRgb(230,172,80));h.Margin=new Thickness(0,14,0,8);content.Children.Add(h);content.Children.Add(Dialogs.Text(topic.Sections[n+1],13));}scroll.ScrollToTop();};for(int i=0;i<topics.Length;i++){int index=i;var button=new Button{Content=topics[i].Name,HorizontalContentAlignment=HorizontalAlignment.Left,Padding=new Thickness(10,12,10,12),Margin=new Thickness(0,0,0,7),FontSize=12};button.Click+=(s,e)=>select(index);buttons.Add(button);menu.Children.Add(button);}select(0);return window;}
 public static void Show(Window owner){Create(owner).ShowDialog();}
